/************************************************************* 
* 함수명   : ShowWin(sval)
* 설명       : 화면 로딩중 표시를 Display 한다.
		   sval : grid ID
*************************************************************/
/**
 * @method
 * @name ShowWin
 * @description
 * @param
 * @hidden Y
 * @exception
 * @example
 */
scwin.ShowWin = function (sval) {
	return; ////미사용

	if ($c.frame.Provider("NoData") != null) {
		$c.frame.Provider("NoData").CloseFrame();
	}
	var tem1 = sval.style.width;
	var temLeft = sval.style.left;
	var temTop = sval.style.top;
	var tem2 = sval.style.height;

	tem1 = tem1.substring(0, (tem1.length - 2));
	temLeft = temLeft.substring(0, (temLeft.length - 2));
	tem2 = tem2.substring(0, (tem2.length - 2));
	temTop = temTop.substring(0, (temTop.length - 2));


	vXpos = (eval(tem1 / 2) - 65) + Number(temLeft);
	vYpos = (eval(tem2 / 2) - 18) + Number(temTop);
	if ($c.frame.Provider("LoadingImg") == null) {
		$c.frame.CreateFrame("LoadingImg", "/common/LoadingImg.gfm", "페이지 로딩중...", vXpos, vYpos, 130, 35, "sunken", 0, 0, true);
	}
};

/************************************************************* 
* 함수명   : ShowWin_yn(sval,boolean)
* 설명       : 화면 로딩중 표시를 Display 한다.
		   sval : grid ID
*************************************************************/
/**
 * @method
 * @name ShowWin_yn
 * @description
 * @param
 * @hidden Y
 * @exception
 * @example
 */
scwin.ShowWin_yn = function (sval, search_yn) {
	if ($c.frame.Provider("NoData") != null) {
		$c.frame.Provider("NoData").CloseFrame();
	}

	if (search_yn) {
		var tem1 = sval.style.width;
		var temLeft = sval.style.left;
		var temTop = sval.style.top;
		var tem2 = sval.style.height;

		tem1 = tem1.substring(0, (tem1.length - 2));
		temLeft = temLeft.substring(0, (temLeft.length - 2));
		tem2 = tem2.substring(0, (tem2.length - 2));
		temTop = temTop.substring(0, (temTop.length - 2));


		vXpos = (eval(tem1 / 2) - 65) + Number(temLeft);
		vYpos = (eval(tem2 / 2) - 18) + Number(temTop);
		if ($c.frame.Provider("LoadingImg") == null) {
			$c.frame.CreateFrame("LoadingImg", "/common/LoadingImg.gfm", "페이지 로딩중...", vXpos, vYpos, 130, 35, "sunken", 0, 0, true);
		}
	}
};

/************************************************************* 
* 함수명   : ShowNoData()
* 설명       : 조회결과가 없음 표시를 Display 한다.
			sval : grid ID
*************************************************************/
/**
 * @method
 * @name ShowNoData
 * @description
 * @param
 * @hidden Y
 * @exception
 * @example
 */
scwin.ShowNoData = function (sval) {
	var tem1 = sval.style.width;
	var temLeft = sval.style.left;
	var temTop = sval.style.top;
	var tem2 = sval.style.height;

	tem1 = tem1.substring(0, (tem1.length - 2));
	temLeft = temLeft.substring(0, (temLeft.length - 2));
	tem2 = tem2.substring(0, (tem2.length - 2));
	temTop = temTop.substring(0, (temTop.length - 2));


	vXpos = (eval(tem1 / 2) - 100) + Number(temLeft);
	vYpos = (eval(tem2 / 2) - 18) + Number(temTop);
	if ($c.frame.Provider("NoData") == null) {
		$c.frame.CreateFrame("NoData", "/common/noData.gfm", "페이지 로딩중...", vXpos, vYpos, 200, 35, "sunken", 0, 0, true);
