/************************************************************* 
* 함수명   : CloseWin()
* 설명       : Display 중인 화면 로딩중 표시를 닫는다.
			cnt : 카운터 0 이면 ShowNoData()호출
			sval : grid id
*************************************************************/
/**
 * @method
 * @name CloseWin
 * @description
 * @param
 * @hidden Y
 * @exception
 * @example
 */
scwin.CloseWin = function (cnt, sval) {
	if ($c.frame.Provider("LoadingImg") != null) {
		$c.frame.Provider("LoadingImg").CloseFrame();
		if (cnt == 0) scwin.ShowNoData(sval);
	}

};

