/*****************************************************************************************
* 함수명   : scwin.PanelToGroupBox()
* 설명       : Panel의 Round를 위해 파라미터로 넘어온 Panel 의 Class 속성값에 따른 함수를 호출한다.
*****************************************************************************************/
/**
 * @method
 * @name PanelToGroupBox
 * @description
 * @param
 * @hidden Y
 * @exception
 * @example
 */
scwin.PanelToGroupBox = function (objPanel) {

	switch (objPanel.className) {
		case "TopCondition_01": scwin.PanelToGroupBox_01(objPanel); break;
		case "Tab_01": scwin.PanelToGroupBox_01(objPanel); break;
		case "Description_01": scwin.PanelToGroupBox_02(objPanel); break;
	}

	//-- 추가 시작 
	//-- 패널의 Visibility 속성이 변경되었을 때, 배경 패널의 Visibility도 함께 바뀌도록 한다.
	objPanel.onpropertychange = function () {
		var orgPanel = event.srcElement;
		var backPanel = document.getElementById("__GROUPBOX_BACKGROUND__" + event.srcElement.id);

		if (orgPanel.style.visibility == "hidden") {
			backPanel.style.visibility = "hidden";
		} else {
			backPanel.style.visibility = "";
		}
	}
	//--  추가 끝
};

/*****************************************************************************************
* 함수명   : scwin.PanelToGroupBox_01()
* 설명       : Panel 의 Class 속성값이 TopCondition_01일 경우에 호출되어 Panel의 Round를 적용시킨다.
*****************************************************************************************/
/**
 * @method
 * @name PanelToGroupBox_01
 * @description
 * @param
 * @hidden Y
 * @exception
 * @example
 */
scwin.PanelToGroupBox_01 = function (objPanel) {

	var vLeft = objPanel.style.left;
	var vTop = objPanel.style.top;
	var vWidth = objPanel.style.width;
	var vPwidth = objPanel.style.pixelWidth;
	var vPheight = objPanel.style.pixelHeight;
	//--  추가 시작 
	var vId = "__GROUPBOX_BACKGROUND__" + objPanel.id;
	var vVisibility = objPanel.style.visibility;
	//--  추가 끝

	// 라운드 테이블을 Panel 뒤 배경으로 붙인다. (포함관계 없음)
	//--  수정 시작 
	//-- 배경 패널의 ID와 Visibility 속성 정의 추가
	var vTableHtml = '<table id="' + vId + '" border="0" cellspacing="0" cellpadding="0" style="position:absolute;width:' + vWidth + ';left:' + vLeft + ';top:' + vTop + ';visibility:' + vVisibility + ';"><tr><td width="10" height="10"><img src="../../img/img_topleftline.gif" width="10" height="10"></td><td height="10" background="../../img/img_leftmiddleline.gif"></td><td width="10" height="10"><img src="../../img/img_toprightline.gif" width="10" height="10"></td></tr><tr><td background="../../img/img_topcenterline.gif">&nbsp;</td><td align="center" bgcolor="d9e9fc">';
	//--  수정 끝

	vTableHtml += '<div style="border:0px solid black;margin:0px;padding:0px;width:' + (vPwidth - 20) + 'px;height:' + (vPheight - 20) + 'px;"></div>';
	vTableHtml += '</td><td background="../../img/img_bottomcenterline.gif">&nbsp;</td></tr><tr><td width="10" height="10"><img src="../../img/img_bottomleftline.gif" width="10" height="10"></td><td height="10" background="../../img/img_rightmiddleline.gif"></td><td><img src="../../img/img_bottomrightline.gif" width="10" height="10"></td></tr></table>';
	//alert(vTableHtml);

	objPanel.insertAdjacentHTML("beforeBegin", vTableHtml);
	// 원 Panel의 border 및 background 정보를 없앤다.
	objPanel.style.border = "";
	objPanel.style.background = "";
};

/*****************************************************************************************
* 함수명   : scwin.PanelToGroupBox_02()
* 설명       : Panel 의 Class 속성값이 Description_01일 경우에 호출되어 Panel의 Round를 적용시킨다.
*****************************************************************************************/
/**
 * @method
 * @name PanelToGroupBox_02
 * @description
 * @param
 * @hidden Y
 * @exception
 * @example
 */
scwin.PanelToGroupBox_02 = function (objPanel) {
	var vLeft = objPanel.style.left;
	var vTop = objPanel.style.top;
	var vWidth = objPanel.style.width;
	var vPwidth = objPanel.style.pixelWidth;
	var vPheight = objPanel.style.pixelHeight;

	//--  추가 시작 
	var vId = "__GROUPBOX_BACKGROUND__" + objPanel.id;
	var vVisibility = objPanel.style.visibility;
	//--  추가 끝

	// 라운드 테이블을 Panel 뒤 배경으로 붙인다. (포함관계 없음)
	//--  수정 시작 
	//-- 배경 패널의 ID와 Visibility 속성 정의 추가
	var vTableHtml = '<table id="' + vId + '" border="0" cellpadding="0" cellspacing="0" style="position:absolute;width:' + vWidth + ';left:' + vLeft + ';top:' + vTop + ';visibility:' + vVisibility + ';"><tr> <td width="10" height="5"><img src="../../img/img_topleftline2.gif" width="10" height="5"></td><td height="5" align="center" background="../../img/img_leftmiddleline2.gif"></td><td width="10"><img src="../../img/img_toprightline2.gif" width="10" height="5"></td></tr><tr> <td background="../../img/img_topcenterline2.gif"></td><td align="center" bgcolor="eeeeee" class="text_d">';
	//--  수정 시작 
	vTableHtml += '<div style="border:0px solid black;margin:0px;padding:0px;width:' + (vPwidth - 20) + 'px;height:' + (vPheight - 10) + 'px;"></div>';
	vTableHtml += '</td><td background="../../img/img_bottomcenterline2.gif"></td></tr><tr> <td width="10" height="5"><img src="../../img/img_bottomleftline2.gif" width="10" height="5"></td><td background="../../img/img_rightmiddleline2.gif"></td><td><img src="../../img/img_bottomrightline2.gif" width="10" height="5"></td></tr></table>';
	objPanel.insertAdjacentHTML("beforeBegin", vTableHtml);

	// 원 Panel의 border 및 background 정보를 없앤다.
	objPanel.style.border = "";
	objPanel.style.background = "";
};


