/**
 * @method
 * @name isurSearch_Rtn
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.isurSearch_Rtn = function (pJongCode, pJongNm, ld_mkt_tp_cd) {

	$p.getComponentById(scwin.js_com_Isurcd.getID($p)).setValue(pJongCode);
	$p.getComponentById(scwin.js_com_Isurnm.getID($p)).setValue(pJongNm);

	try {
		if (typeof $p.parent().scwin.afterExce != "undefined") {
			$p.parent().scwin.afterExce();
		}
	} catch (E) { }

	try {
		if (typeof $p.parent().scwin.afterExecGfm != "undefined") {
			$p.parent().scwin.afterExec(pJongCode, ld_mkt_tp_cd);
		}
	} catch (E) { }
};

