	// 2009.12.07(횝사팝업창에서 'js_bond_yn' 가 선언되어 있지 않을시 스크립트 오류발생. 인클루드 되어있지않을시 'N'으로 셋팅 P.H.J)
	// try{
	//     $c.session.getUserInfo("js_bond_yn") = $c.session.getUserInfo("js_bond_yn");
	// }catch(E){
	//     $c.session.getUserInfo("js_bond_yn") = "N";
	// }

	// 2009.09.01 채권공시관련 추가
	if ($c.session.getUserInfo("js_bond_yn") == 'Y') {
		url = "/api/discls/common/popup/select-list-isur-cd-value?listStatCd=Y&comAbbrv=" + comAbbrv;
	} else {
		url = "/api/discls/common/popup/select-list-isur-cd-value?mktTpCd=" + scwin.js_com_market + "&listStatCd=&comAbbrv=" + comAbbrv;
	}

	const dcOptions = {
		baseNode: "list",
		repeatNode: "map",
		saveRemovedData: "true"
	};

	let dltObj = $c.data.createDataList("dlt_isurCd", ["isurCd", "comNm", "comAbbrv", "comEngAbbrv", "listStatCd", "spotIsuTrdMktTpCd", "oldComAbbrv"], ["text", "text", "text", "text", "text", "text", "text"], dcOptions);
	let gridObj = {
		"nodeset": "data:" + dltObj.getID(), "value": "isurCd", "label": "comAbbrv", 
		"item": [
			{ "ref": "spotIsuTrdMktTpCd", "header": "시장구분", "style": "width:90px;height:25px", "headerStyle": "height:28px", "hidden": "false", "sortable": "false" },
			{ "ref": "listStatCd", "header": "상장구분코드", "style": "width:90px;height:25px", "headerStyle": "height:28px", "hidden": "true", "sortable": "false" }, // "headerStyle": "height:0px;display:none"
			{ "ref": "comAbbrv", "header": "회사명", "style": "width:310px;text-align:left", "headerStyle": "", "sortable": "false" },
			{ "ref": "isurCd", "header": "발행기관코드", "style": "width:115px", "headerStyle": "", "sortable": "false", "showSortableImage": "false" },
			{ "ref": "oldComAbbrv", "header": "oldComAbbrv", "style": "width:150px", "headerStyle": "", "hidden": "true", "sortable": "false" }
		]
		, "id": "grdIsurCd", "width": "510", "label": "comAbbrv", "autoFit": "none", "value": "isurCd", "visibleRowNum": "10", "sortable": "false", "showSortableImage": "false"
	};

	codeComp.setGridItemset(gridObj);

	// 회사코드 취득
	let isurInfo = [];
	const isurCodeOption = {
		id: "sbm_isurCode",
		action: url,
		method: "get",
		isProcessMsg: false
	};

	let res = await $c.sbm.executeDynamic(isurCodeOption, {});
	if (res.responseJSON.success === true) {
		dltObj.setJSON(res.responseJSON.body);
	}

	WebSquare.getBody().getLayerListener().show(codeComp.getID(), {});
	WebSquare.getBody().getLayerListener().hide(codeComp.getID(), {});

	const gridView = scwin.js_com_Isurcd?.itemTable.gridView;

	//gridView.options.showSortableImage = false;

	gridView?.setSortable(gridView.getHeaderColID(0), false);
	gridView?.setSortable(gridView.getHeaderColID(1), false);
	gridView?.setSortable(gridView.getHeaderColID(2), false);
	gridView?.setSortable(gridView.getHeaderColID(3), false);
	gridView?.setSortable(gridView.getHeaderColID(4), false);

	// gridView?.setHeaderSortImage(gridView.getHeaderColID(0), 0, 0);
	// gridView?.setHeaderSortImage(gridView.getHeaderColID(1), 0, 0);
	// gridView?.setHeaderSortImage(gridView.getHeaderColID(2), 0, 0);
	// gridView?.setHeaderSortImage(gridView.getHeaderColID(3), 0, 0);
	// gridView?.setHeaderSortImage(gridView.getHeaderColID(4), 0, 0);

	// customFormatter 설정
	gridView.setCustomFormatter("spotIsuTrdMktTpCd", scwin.__setSpotIsuTrdMktTpCdFormatter);

	// label 설정 이벤트
	codeComp.unbind("onviewchange");
	codeComp.bind("onviewchange", function (info) {
		//console.log("onviewchange info === ", info);
		let comAbbrv = this.getScopeWindow().dlt_isurCd.getCellData(info.newSelectedIndex, "comAbbrv");
		if (info.newValue == "" || info.newSelectedIndex === -1) comAbbrv = "";
		labelComp.setValue(comAbbrv);

		scwin.fn_com_isur_value = info.newValue;
	}); 

	// label 설정 이벤트
	codeComp.unbind("oneditend");
	codeComp.bind("oneditend", function (value) {
		//console.log("oneditend value === ", value, scwin.fn_com_isur_value);
		if ($c.util.isEmpty(value) || (scwin.fn_com_isur_value !== "" && value !== scwin.fn_com_isur_value)) {
			comAbbrv = "";
			labelComp.setValue(comAbbrv);
		}

		scwin.fn_com_isur_value = value;
	});

	// label 설정 이벤트
	codeComp.unbind("oneditenter");
	codeComp.bind("oneditenter", function () {
		//console.log("oneditenter === ");
		const gridView = scwin.js_com_Isurcd?.itemTable.gridView;
		const isurCd = gridView.getCellData(0, "isurCd");

		if (gridView?.getRowCount() === 1 && codeComp.dom.input.value === isurCd) {
			labelComp.setValue(gridView.getCellData(0, "comAbbrv"));
			scwin.fn_com_isur_value = gridView.getCellData(0, "isurCd");
		}
	});

	// emptyItem=true인 경우 keepValue 속성이 설정되지 않아 강제 설정
	codeComp.noResult = "keepValue";
	codeComp.options.noResult = "keepValue";

	// 코드 초기화
	codeComp.setValue("");
	codeComp.selectedIndex = -1;
    codeComp.dom.label.textContent = "";
    codeComp.dom.input.value = "";
};

/**
 * @method
 * @name __setSpotIsuTrdMktTpCdFormatter
 * @description gridView > CustomFormatter
 * @param
 * @hidden Y
 * @exception
 * @example
 */
scwin.__setSpotIsuTrdMktTpCdFormatter = function(data, formattedData, rowIndex, colIndex) {

	const listStatCd = this.getCellData(rowIndex, "listStatCd");
	let fontColor = "#49515B";

	if (listStatCd.toUpperCase() === "Y") {
		fontColor = "#49515B";
	} else if (listStatCd.toUpperCase() === "D") {
		fontColor = "#FF0033";
	} else if (listStatCd.toUpperCase() === "N") {
		fontColor = "#009933";
	}

	this.setRowColor(rowIndex, fontColor);

	let returnData = "";

	// 1:유,2:코,5:프,6:넥,9:기
	if (data === "1") {
		returnData = "유";
	} else if (data === "2") {
		returnData = "코";
	} else if (data === "5") {
		returnData = "프";
	} else if (data === "6") {
		returnData = "넥";
	} else if (data === "9") {
		returnData = "기";
	}

	return returnData;
};

