/**
 * @method
 * @name isNumber
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.isNumber = function (sVal) {
	if (('0' < sVal) || ('9' > sVal)) {
		return true;
	} else {
		return false;
	}
};

//Ajax 사용하기 위한 함수(2009.11.20 P.H.J)
/**
 * @method
 * @name xmlDocLoad
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.xmlDocLoad = function (strXml) {
	xmlDoc = new ActiveXObject("Microsoft.XMLDOM");
	xmlDoc.async = false;

	if (!xmlDoc.loadXML(strXml)) {
		alert("error:" + xmlDoc.parseError.reason);
		//gSetXMLDataSync = false;
		xmlDoc = "";
		return "";
	}
	return xmlDoc;
};

