	var cL = 7;
	var cT = 53;

	if (grdObj == "" || grdObj2 == "") {
		scwin.obj_left = "30";
		scwin.obj_top = "50";
	} else {
		scwin.obj_left = grdObj.style.left;
		scwin.obj_left = scwin.obj_left.substring(0, scwin.obj_left.length - 2);

		scwin.obj_left = eval(scwin.obj_left) + cL;
		scwin.obj_top = grdObj.style.top;
		scwin.obj_top = obj_top.substring(0, scwin.obj_top.length - 2);
		scwin.obj_top = eval(scwin.obj_top) + cT;
	}
};

