		strH = "630";
		strTitle = "CD";
	} else if (KND == "77") {
		strUrl = "ULDINS92800";
		strW = "770";
		strH = "740";
		strTitle = "전자단기사채";
	} else if (KND == "07") {
		strUrl = "ULDINS92700"; // CP
		strW = "770";
		strH = "700";
		strTitle = "CP";
	} else if (KND == "10") { //주식워런트증권(ELW)
		strUrl = "ULDINS92400";
		strW = "770";
		strH = "830";
		strTitle = "주식워런트증권(ELW)";
	} else if (KND == "12") {
		strUrl = "ULDINS94100";  // ETN
		strW = "770";
		strH = "670";
		strTitle = "ETN";
	} else if (KND == "13") {
		strUrl = "ULDINS94200";  //투자계약증권
		strW = "770";
		strH = "670";
		strTitle = "투자계약증권";
	}

	if (strUrl == "") { $c.win.alert("유가증권종류 확인 불가 \n 상세정보를 조회할 수 없습니다."); return; }

	//alert(strTitle);
	strTitle = "* 신청 [" + strTitle + " 상세_" + strUrl + "]";
	strW = parseInt(strW) + 10;
	strH = parseInt(strH) + 10;

	// 팝업 오픈
	const url = "/ui/ins/common/" + strUrl + ".xml";
	const param = {};

	const options = {
        id: "ins_popup",
        popupName: strTitle,
        frameModal: "top",
		width: strW,
		height: strH,
    };

	$c.win.openPopup(url, options, param);		
};

