/**
 * @method
 * @name fn_DelChar
 * @description ins
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_DelChar = function (Obj) {

	var limit_char = /[~!@#$%^&*\\=+|:;?"<,.>/`()_']/g
	var numstr = Obj.getValue();

	if (limit_char.test(numstr)) {
		numstr = numstr.replace(limit_char, '');
		Obj.setValue(numstr);
	}

	// setObjectValue(txb_pMBR_NM, escape(last_char).length);
};

