/**
 * 발행년코드
 * 2005년을 5으로 기준하여... 2034년  W로 하여(5 ~4, A~W )까지...순차적 ( 알파벳 I,O,U  는제외)
 * 30년을 주기로 반복한다.
 *
 * @param yyyy
 * @return
 */
/**
 * @method
 * @name get_YYYY_Cd_for_elw
 * @description ins
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.get_YYYY_Cd_for_elw = function (yyyy) {
	var i_yyyy = 0;
	var yyyy_cd = new Array("5", "6", "7", "8", "9", "0", "1", "2", "3", "4",
		"A", "B", "C", "D", "E", "F", "G", "H", "J", "K",
		"L", "M", "N", "P", "Q", "R", "S", "T", "V", "W");
	i_yyyy = (parseInt(yyyy) - 2005) % 30;

	return yyyy_cd[i_yyyy];
};

//날짜 체크 (param 날짜 obj)
/**
 * @method
 * @name fn_CheckDateObj
 * @description ins
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckDateObj = function (obj, objNm) {
	if ($c.stf.getObjectValue(obj) == null || $c.stf.getObjectValue(obj) == '') {
		return false;
	}

	var yyyy;
	var mm;
	var dd;
	yyyy = scwin.fn_Trim($c.stf.getObjectValue(obj).substring(0, 4)).replace(" ", "");
	mm = scwin.fn_Trim($c.stf.getObjectValue(obj).substring(4, 6));
	dd = scwin.fn_Trim($c.stf.getObjectValue(obj).substring(6, 8));

	if (yyyy == '' || yyyy.length < 4) {
		$c.win.alert(objNm + " : 년을 제대로 입력해주세요.");
		obj.focus();
		return true;
	}

	if (!scwin.fn_IsNumber_val(yyyy)) {
		$c.win.alert(objNm + " : 숫자만 입력하셔야 합니다.");
		obj.focus();
		return true;
	}

	if (!scwin.fn_IsNumber_val(mm)) {
		$c.win.alert(objNm + " : 숫자만 입력하셔야 합니다.");
		obj.focus();
		return true;
	}

	if (!scwin.fn_IsNumber_val(dd)) {
		$c.win.alert(objNm + " : 숫자만 입력하셔야 합니다.");
		obj.focus();
		return true;
	}

	var year = Number(yyyy);
	var month = Number(mm);
	var day = Number(dd);

	if (month == 1) total_days = 31;
	else if (month == 2) {
		if (((year % 4 == 0) && (year % 100 != 0)) || (year % 400 == 0))
			total_days = 29;
		else
			total_days = 28;
	}
	else if (month == 3) total_days = 31;
	else if (month == 4) total_days = 30;
	else if (month == 5) total_days = 31;
	else if (month == 6) total_days = 30;
	else if (month == 7) total_days = 31;
	else if (month == 8) total_days = 31;
	else if (month == 9) total_days = 30;
	else if (month == 10) total_days = 31;
	else if (month == 11) total_days = 30;
	else if (month == 12) total_days = 31;
	else {
		$c.win.alert(objNm + " : 존재하지 않는 월입니다.");
		obj.focus();
		return true;
	}

	if (year <= 0) {
		$c.win.alert(objNm + " : 존재하지 않는 년도입니다.");
		obj.focus();
		return true;
	}

	if (month <= 0) {
		$c.win.alert(objNm + " : 존재하지 않는 월입니다.");
		obj.focus();
		return true;
	}

	if (day > total_days) {
		$c.win.alert(objNm + " : 존재하지 않는 날짜입니다.");
		obj.focus();
		return true;
	}

	if (day <= 0) {
		$c.win.alert(objNm + " : 존재하지 않는 날짜입니다.");
		obj.focus();
		return true;
	}

	if (mm.length == 1) {
		$c.win.alert(objNm + " : 존재하지 않는 월입니다.");
		obj.focus();
		return true;
	}

	if (dd.length == 1) {
		$c.win.alert(objNm + " : 존재하지 않는 날짜입니다.");
		obj.focus();
		return true;
	}
	return false;
};

//날짜 체크 (param 날짜 value)
/**
 * @method
 * @name fn_CheckDateVal
 * @description ins
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckDateVal = function (param) {
	var val = scwin.fn_Trim(param);
	if (val == null || val == '') {
		return true;
	}

	if (val.length != 8) {
		return true;
	}

	var yyyy;
	var mm;
	var dd;
	yyyy = scwin.fn_Trim(val.substring(0, 4)).replace(" ", "");
	mm = scwin.fn_Trim(val.substring(4, 6));
	dd = scwin.fn_Trim(val.substring(6, 8));

	if (yyyy == '' || yyyy.length < 4) {
		return true;
	}
	if (!scwin.fn_IsNumber_val(yyyy)) {
		return true;
	}
	if (!scwin.fn_IsNumber_val(mm)) {
		return true;
	}
	if (!scwin.fn_IsNumber_val(dd)) {
		return true;
	}

	var year = Number(yyyy);
	var month = Number(mm);
	var day = Number(dd);

	if (month == 1) total_days = 31;
	else if (month == 2) {
		if (((year % 4 == 0) && (year % 100 != 0)) || (year % 400 == 0))
			total_days = 29;
		else
			total_days = 28;
	}
	else if (month == 3) total_days = 31;
	else if (month == 4) total_days = 30;
	else if (month == 5) total_days = 31;
	else if (month == 6) total_days = 30;
	else if (month == 7) total_days = 31;
	else if (month == 8) total_days = 31;
	else if (month == 9) total_days = 30;
	else if (month == 10) total_days = 31;
	else if (month == 11) total_days = 30;
	else if (month == 12) total_days = 31;
	else {
		return true;
	}
	if (year <= 0) {
		return true;
	}
	if (month <= 0) {
		return true;
	}
	if (day > total_days) {
		return true;
	}
	if (day <= 0) {
		return true;
	}
	if (mm.length == 1) {
		return true;
	}
	if (dd.length == 1) {
		return true;
	}
	return false;
};

//문자열 앞뒤 공백 제거
/**
 * @method
 * @name fn_Trim
 * @description ins
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_Trim = function (_str) {
	return _str.replace(/^\s{1,}/, "").replace(/\s{1,}$/, "");
};

//숫자인지 체크
/**
 * @method
 * @name fn_IsNumber_val
 * @description ins
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_IsNumber_val = function (_val) {
	str = scwin.fn_IgnoreSpaces(_val);
	for (i = 0; i < str.length; i++) {
		if (isNaN(str.substr(i, 1)) == true) {
			//_obj.select();
			return false;
		}
	}
	return true;
};

//문자열에서 모든 공백 제거
/**
 * @method
 * @name fn_IgnoreSpaces
 * @description ins
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_IgnoreSpaces = function (_str) {
	return _str.replace(/\s/g, "");
};

/******************************************************************* 
 * 함수명   : fn_ChgAmtToHan()
 * 설명     : 금액 한글 변환 한다.
 * argument : dtsObj
*******************************************************************/
/**
 * @method
 * @name fn_ChgAmtToHan
 * @description ins
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ChgAmtToHan = function (str) {
	if (str == '' || str == undefined) return '';
	var won = new Array();
	var han1 = new Array("", "일", "이", "삼", "사", "오", "육", "칠", "팔", "구");
	var han2 = new Array("", "십", "백", "천");
	var han3 = new Array("", "만", "억", "조", "경");

	var han = '';
	var len = str.length;
	for (var i = len - 1; i >= 0; i--) {
		won[i] = han1[str.substring(len - i - 1, len - i)];
		if (i > 0 && won[i] != '') won[i] += han2[i % 4];
		if (i % 4 == 0) won[i] += han3[i / 4];
	}

	for (var i = len - 1; i >= 0; i--) {
		if (won[i].length == 2) won[i - i % 4] += '-';
		if (won[i].length == 1 && i > 0) won[i] = '';
		if (i % 4 != 0) won[i].replace('일', '');
	}

	won = won.reverse().join('').replace(/-+/g, '');

	return '(' + won + ')';
};

/************************************************************* 
* 함수명   : ins_cfi_set(dtsObj, vScrenID, SCREN_PROCS_TP_CD, std_cd_prod_tp_cd, category, group, attr_cipher, searchDiv)
* 설명       :   
* dtsObj : 콤보 Object
* vScrenID: 화면ID 
* SCREN_PROCS_TP_CD : 조회 01
* std_cd_prod_tp_cd : 상품구분
* category : 선택카테고리
* group : 선택그룹
* attr_cipher : 가져올 속성구분
* searchDiv : 그룹조회(G) / 속성조회(A) 구분
*************************************************************/
/**
 * @method
 * @name ins_cfi_set
 * @description ins
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.ins_cfi_set = function (dtsObj, vScrenID, SCREN_PROCS_TP_CD, std_cd_prod_tp_cd, category, group, attr_cipher, searchDiv) {

	var query_id = "";
	if (searchDiv == "G") {
		query_id = "lds.ins.etc.select.cficd.group"; // 그룹조회
		attr_cipher = "2";
	} else {
		query_id = "lds.ins.etc.select.cficd.attr"; // 속성조회
		category += group;
	}

	//데이터를 우선 지우고 신청ID가 없으면 스탑
	dtsObj.ClearData();

	var url = "/listingCommon.do?SCREN_ID=" + vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD + "&method=listGeneralForDynamicName" +
		"&outputMessageId=CFI_CD_OUT" +
		"&service=krx.lds.ins.listingcommon.services.ListingCommonApp" +
		"&queryId=" + query_id +
		"&{P}std_cd_prod_tp_cd=" + std_cd_prod_tp_cd +
		"&{P}category=" + category +
		"&{P}attr_cipher=" + attr_cipher;

	dtsObj.DataID = encodeURI(url);
	dtsObj.reset();
};

//신청버튼 클릭시 마이너스값 입력체크 
/**
 * @method
 * @name fn_minusCheck
 * @description ins
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_minusCheck = function (obj, title) {
	var temp = $c.stf.getObjectValue(obj);
	var result = "X";

	if (temp.indexOf('-') != -1) {
		if ($c.win.confirm("[" + title + "] 마이너스(-) 값을 입력하셨습니다. 이대로 진행하시겠습니까?")) {
			result = "Y";

		} else {
			obj.focus();
			result = "N";
		}
	}
	return result;
};

